import{_ as e,o as t,c as i,a1 as o}from"./chunks/framework.BZ8LM4kv.js";const r="data:image/webp;base64,",s="/assets/v0-templates.BTiGVEh8.webp",l="/assets/huemint-palette.aPw3WCxB.webp",n="/assets/github-repository.DKfAn4Zt.webp",m=JSON.parse('{"title":"搭建一个静态博客网站","description":"从工具准备、灵感搜集到 GitHub Pages 发布，记录我搭建个人静态博客的过程与后续计划。","frontmatter":{"title":"搭建一个静态博客网站","description":"从工具准备、灵感搜集到 GitHub Pages 发布，记录我搭建个人静态博客的过程与后续计划。","date":"2026-11-11T00:00:00.000Z","category":"博客","tags":["静态博客","VitePress","GitHub Pages"],"draft":false},"headers":[],"relativePath":"articles/build-a-static-blog.md","filePath":"articles/build-a-static-blog.md","lastUpdated":1794496288000}'),p={name:"articles/build-a-static-blog.md"};function c(u,a,h,d,A,b){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="搭建一个静态博客网站" tabindex="-1">搭建一个静态博客网站 <a class="header-anchor" href="#搭建一个静态博客网站" aria-label="Permalink to &quot;搭建一个静态博客网站&quot;">​</a></h1><p>搭建自己的静态博客，是我这段时间做得比较完整的一件事。这篇文章记录我所用的工具、搭建博客的原因，以及从寻找设计参考到上线发布的整个过程。</p><h2 id="_1-需要的工具" tabindex="-1">1. 需要的工具 <a class="header-anchor" href="#_1-需要的工具" aria-label="Permalink to &quot;1. 需要的工具&quot;">​</a></h2><ol><li>GitHub 账号</li><li>VPN 工具</li><li>好用的 Agent 工具，这里推荐 DeepSeek Harness</li></ol><p><img src="'+r+'" alt="DeepSeek Harness"></p><h2 id="_2-为什么我想搭建个人博客" tabindex="-1">2. 为什么我想搭建个人博客 <a class="header-anchor" href="#_2-为什么我想搭建个人博客" aria-label="Permalink to &quot;2. 为什么我想搭建个人博客&quot;">​</a></h2><p>从就业的角度来看，个人博客相比普通简历能够更好地展示自己的优势，也更容易一下子抓住面试官的眼球。</p><p>当然，更主要的原因是，我认为做网站十分有趣。可以在网络上拥有一个属于自己的私人空间，在上面发发牢骚，最重要的是能够记录自己成长的历程和所思所想。</p><h2 id="_3-如何制作一个个人博客" tabindex="-1">3. 如何制作一个个人博客 <a class="header-anchor" href="#_3-如何制作一个个人博客" aria-label="Permalink to &quot;3. 如何制作一个个人博客&quot;">​</a></h2><p>对于个人网站，我认为对新手来说最重要的是模板和 UI 选择，也就是整个网站的设计。</p><p>作为一个新手，我们往往没有什么灵感，这时候可以从模仿开始，走前人已经走过的路。以下是我常用的灵感搜集网站：</p><ul><li><a href="https://huemint.com/website-1/" target="_blank" rel="noreferrer">Huemint 配色</a></li><li><a href="https://v0.app/templates" target="_blank" rel="noreferrer">v0 模板库</a></li><li><a href="https://www.figma.com/community" target="_blank" rel="noreferrer">Figma 社区</a></li></ul><p>我们可以在这些网站中搜索关键词 “portfolio”，找到设计师们优秀的作品。学习他们的灵感之后，再把这些设计融入自己的博客制作中。</p><p><img src="'+s+'" alt="在 v0 模板库搜索 portfolio"></p><p>第二个推荐是经过市场验证的配色方案页面。你可以不断筛选，找到自己喜欢的颜色搭配，再应用到个人博客中。</p><p><img src="'+l+'" alt="Huemint 配色方案"></p><p>之后在 GitHub 上创建一个个人博客仓库。每实现一个功能、修复一个 bug，就把改动提交到仓库中。</p><p><img src="'+n+'" alt="GitHub 博客仓库"></p><h2 id="_4-如何在不使用服务器的情况下让别人看到网站" tabindex="-1">4. 如何在不使用服务器的情况下让别人看到网站 <a class="header-anchor" href="#_4-如何在不使用服务器的情况下让别人看到网站" aria-label="Permalink to &quot;4. 如何在不使用服务器的情况下让别人看到网站&quot;">​</a></h2><p>我们把做完的前端页面源代码打包，然后发布到另一个仓库，利用 GitHub Pages 免费托管，就可以让别人访问我们的博客。</p><p>整个网站不需要后端、数据库或服务器运行时，维护成本很低。</p><h2 id="_5-后续打算" tabindex="-1">5. 后续打算 <a class="header-anchor" href="#_5-后续打算" aria-label="Permalink to &quot;5. 后续打算&quot;">​</a></h2><p>我会在有一定经济条件的情况下，选择租借一台云服务器，把这个项目不断完善，并加入后端功能，使它逐渐成长为一个完整的全栈项目。</p><p>谢谢你的阅读。</p>',24)])])}const q=e(p,[["render",c]]);export{m as __pageData,q as default};
